'use strict';
// Coche: Audi R8 LMS Evo GT3 (2020)
// - Motor 5.2L V10 atmosférico FSI a 8.500 RPM con 585 CV y 550 Nm de par.
// - Tracción trasera (reglamento FIA GT3) con cambio secuencial de 6 velocidades.
// - Aerodinámica Evo con splitter frontal afilado, calandra Singleframe y difusor trasero gigante.
// - Aullido inconfundible del V10 atmosférico de competición que corta a 8.600 RPM.
(() => {

const ATLAS_B64 = "data:image/png;base64,";
const BODY_V = "";
const BODY_I = "";
const GLASS_V = "";
const GLASS_I = "";
const WHEEL_V = "";
const WHEEL_I = "";


WGSL["mat_audi_r8_lms_evo"] = `// Material Audi R8 LMS Evo
#include mesh_vert
@group(3) @binding(0) var tAtlas: texture_2d<f32>;

fn surf(in: V2F, ff: bool) -> Surface {
  var s = surfDefault(normalize(in.nrm));
  if (!ff) { s.normal = -s.normal; }

  let id = matId(in.mat);
  let uv = in.uv;
  let tx = textureSample(tAtlas, sLin, uv);

  if (id == 3u) {
    // Carrocería Audi Sport Oficial (Rojo Misano / Plata / Negro Mate)
    s.albedo = tx.rgb;
    s.metal = 0.12;
    s.rough = 0.15;
    s.coat = 0.95;
  } else if (id == 16u) {
    // Llantas forjadas Audi Sport
    s.albedo = tx.rgb;
    s.metal = 0.85;
    s.rough = 0.22;
    s.coat = 0.40;
  } else if (id == 1u) {
    // Ópticas delanteras Matrix LED de competición
    s.albedo = tx.rgb;
    s.emissive = 1.0;
    s.rough = 0.05;
  } else if (id == 2u) {
    // Pilotos traseros LED dinámicos Audi Sport
    s.albedo = tx.rgb;
    s.emissive = 0.9;
    s.rough = 0.10;
  } else if (id == 4u || id == 30u) {
    // Carbono visto (splitter, calandra, difusor, alerón de cuello de cisne)
    s.albedo = tx.rgb;
    s.metal = 0.08;
    s.rough = 0.30;
    s.coat = 0.60;
  } else {
    s.albedo = tx.rgb;
    s.metal = 0.15;
    s.rough = 0.35;
  }

  return s;
}
`;

function loadAtlas() {
  const W = 2048, H = 2048;
  const tex = mkTex(W, H, 'rgba8unorm-srgb', TU.RT | TU.TB | TU.CD, { mipLevelCount: 7 });
  const initData = new Uint8Array(W * H * 4);
  initData.fill(40);
  G.dev.queue.writeTexture({ texture: tex }, initData, { bytesPerRow: W * 4 }, [W, H]);

  if (typeof Image !== 'undefined') {
    const img = new Image();
    img.src = ATLAS_B64;
    img.onload = () => {
      if (typeof createImageBitmap !== 'undefined') {
        createImageBitmap(img).then(bmp => {
          G.dev.queue.copyExternalImageToTexture({ source: bmp }, { texture: tex }, [W, H]);
          if (typeof genMips === 'function') genMips(tex, 'rgba8unorm-srgb');
        }).catch(() => {
          const cvs = document.createElement('canvas');
          cvs.width = W; cvs.height = H;
          const ctx2d = cvs.getContext('2d');
          ctx2d.drawImage(img, 0, 0);
          const id = ctx2d.getImageData(0, 0, W, H);
          G.dev.queue.writeTexture({ texture: tex }, id.data, { bytesPerRow: W * 4 }, [W, H]);
          if (typeof genMips === 'function') genMips(tex, 'rgba8unorm-srgb');
        });
      } else {
        const cvs = document.createElement('canvas');
        cvs.width = W; cvs.height = H;
        const ctx2d = cvs.getContext('2d');
        ctx2d.drawImage(img, 0, 0);
        const id = ctx2d.getImageData(0, 0, W, H);
        G.dev.queue.writeTexture({ texture: tex }, id.data, { bytesPerRow: W * 4 }, [W, H]);
        if (typeof genMips === 'function') genMips(tex, 'rgba8unorm-srgb');
      }
    };
  }
  return tex;
}

const CAR = {
  id: 'audi-r8-lms-evo-2020',
  name: 'Audi R8 LMS Evo',
  subtitle: '2020 GT3 Spec · 5.2L Naturally-Aspirated V10 · RWD',
  specs: '1225 kg · 585 CV · 6-vel seq · RWD · Audi Sport Aero',
  accent: '#e60000',
  physics: {
    m: 1225, Izz: 1710, L: 2.700, a: 1.350, b: 1.350, tw: 1.65, h: 0.38, R: 0.345,
    mu: 1.72, B: 11.3, C: 1.53, driveF: 0.0,
    gears: [2.92, 2.15, 1.68, 1.34, 1.11, 0.92], final: 3.44, rev: 3.2, eff: 0.96,
    cdA: 0.67, crr: 0.010, brakeF: 0.61, halfW: 1.02, front: 2.45, rear: 2.40,
    clA: 0.94, aeroSplitF: 0.40,
    torqueBase: 360, torquePeak: 260, torqueDrop: 140, torquePeakStart: 0.50, torquePeakSpan: 5.5, torqueDropRpm: 8.2,
    shiftUpRpm: 8400, shiftDownRpm: 6000, revLimitRpm: 8600, maxRpm: 8800, idleRpm: 1400,
  },
  hud: { maxKmh: 335, maxRpm: 9.0, redlineRpm: 8.5 },
  wheelbase: 2.700, trackF: 1.652, trackR: 1.633, wheelR: 0.345,
  hubs: [
    [1.350, 0.337, -0.826],
    [1.350, 0.337, 0.826],
    [-1.350, 0.352, -0.817],
    [-1.350, 0.352, 0.817]
  ],
  slotBody: 0, slotWheel: [0, 0, 0, 0],
  tris: 0, _t: m4(), _t2: m4(), _t3: m4(), set: null, glass: null, atlasBG: null, fam: null,
  _z4: new Float32Array(4),
  inp: new Float64Array(2),

  build() {
    const fam = CAR.fam = mkFamily('car_audi_r8_lms_evo', { src: 'mat_audi_r8_lms_evo', noCube: true });
    CAR.slotBody = objSlot();
    for (let i = 0; i < 4; i++) CAR.slotWheel[i] = objSlot();

    const set = CAR.set = new MeshSet(fam);
    const mb = new MeshBuilder(1 << 19);
    const w = new MeshBuilder(1 << 16);

    const bV = b64ToF32(BODY_V), bI = b64ToU32(BODY_I);
    const wV = b64ToF32(WHEEL_V), wI = b64ToU32(WHEEL_I);

    const nbV = bV.length / 9;
    for (let i = 0; i < nbV; i++) {
      mb.mat(bV[i*9 + 8]);
      mb.v(bV[i*9], bV[i*9+1], bV[i*9+2], bV[i*9+3], bV[i*9+4], bV[i*9+5], bV[i*9+6], bV[i*9+7]);
    }
    for (let i = 0; i < bI.length; i += 3) mb.tri(bI[i], bI[i+1], bI[i+2]);

    const nwV = wV.length / 9;
    for (let i = 0; i < nwV; i++) {
      w.mat(wV[i*9 + 8]);
      w.v(wV[i*9], wV[i*9+1], wV[i*9+2], wV[i*9+3], wV[i*9+4], wV[i*9+5], wV[i*9+6], wV[i*9+7]);
    }
    for (let i = 0; i < wI.length; i += 3) w.tri(wI[i], wI[i+1], wI[i+2]);

    CAR.tris = mb.ni / 3;
    set.add(mb.upload(), CAR.slotBody, 3);

    const wm = w.upload();
    CAR.tris += 4 * w.ni / 3;
    for (let i = 0; i < 4; i++) set.add(wm, CAR.slotWheel[i], 3);

    const glass = CAR.glass = new GlassSet();
    const gl = new MeshBuilder(1 << 15);
    const gV = b64ToF32(GLASS_V), gI = b64ToU32(GLASS_I);
    const ngV = gV.length / 9;
    for (let i = 0; i < ngV; i++) {
      gl.mat(gV[i*9 + 8]);
      gl.v(gV[i*9], gV[i*9+1], gV[i*9+2], gV[i*9+3], gV[i*9+4], gV[i*9+5], gV[i*9+6], gV[i*9+7]);
    }
    for (let i = 0; i < gI.length; i += 3) gl.tri(gI[i], gI[i+1], gI[i+2]);
    CAR.tris += gl.ni / 3;
    glass.add_(gl.upload(), CAR.slotBody);
    R.transparents.push(glass);

    const tex = loadAtlas();
    R.drawables.push({
      draw(pass, ctx) {
        if (ctx.kind === KIND.SHADOW && ctx.cascade === 3) return;
        if (!CAR.atlasBG) {
          if (!fam.bgl3) return;
          CAR.atlasBG = G.dev.createBindGroup({ layout: fam.bgl3, entries: [{ binding: 0, resource: tex.createView() }] });
        }
        pass.setBindGroup(3, CAR.atlasBG);
        set.draw(pass, ctx);
      },
    });

    m4ident(CAR._t);
    CAR.place(CAR._t, CAR._z4, CAR._z4);
    CAR.place(CAR._t, CAR._z4, CAR._z4);
    console.log('[Audi R8 LMS Evo] Inicializado con éxito. Triángulos:', CAR.tris);
  },

  place(body, spin, susp) {
    const steer = CAR.inp[0];
    const t = CAR._t2;
    objPrev(CAR.slotBody).set(objModel(CAR.slotBody));
    objModel(CAR.slotBody).set(body);
    for (let i = 0; i < 4; i++) {
      const sl = CAR.slotWheel[i], h = CAR.hubs[i], left = (i & 1) === 0;
      objPrev(sl).set(objModel(sl));
      const a = -(i < 2 ? steer : 0) + (left ? PI : 0), c = Math.cos(a), sn = Math.sin(a);
      const g = left ? spin[i] : -spin[i], cg = Math.cos(g), sg = Math.sin(g);
      t[0] = c * cg; t[1] = sg; t[2] = -sn * cg; t[3] = 0;
      t[4] = -c * sg; t[5] = cg; t[6] = sn * sg; t[7] = 0;
      t[8] = sn; t[9] = 0; t[10] = c; t[11] = 0;
      t[12] = h[0]; t[13] = h[1] + susp[i]; t[14] = h[2]; t[15] = 1;
      m4mul(objModel(sl), body, t);
    }
  },
};

CARS.register(CAR);
})();
